// ----- 8< ----- FILE "./S011HD1P_X32Y2D128_BW.v" ----- 8< -----

module S011HD1P_X32Y2D128_BW(
  output reg [127:0]                Q,
  input                                     CLK,
  input                                     CEN,
  input                                     WEN,
  input      [127:0]                BWEN,
  input      [5:0] A,
  input      [127:0]                D
);
  reg [127:0] ram [0:63];
  always @(posedge CLK) begin
    if (!CEN && !WEN) begin
      ram[A] <= (D & ~BWEN) | (ram[A] & BWEN);
    end
    Q <= !CEN ? (WEN ? ram[A] : (D & ~BWEN) | (ram[A] & BWEN)) : {4{32'hdead_feed}};
  end
endmodule
    	// ../test/corvus-compiler/YuQuan.hw.mlir:11431:5
