module RamWrite (
  input  clock,
  input  wen,
  input  [63:0] addr,
  input  [63:0] data,
  input  [ 7:0] mask
);

  always@(posedge clock) begin
    if (wen) ram_write(addr, data, mask);
  end

endmodule
